using System;using System.IO;using System.Reflection;using System.Collections;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using App=Autodesk.AutoCAD.ApplicationServices.Application;
public class OpenScanTest{
[CommandMethod("OPEN_SCAN_TEST")]public void Run(){string root=@"F:\Codedemo\XJG批量打印_fix";string result="";try{var asm=Assembly.Load(File.ReadAllBytes(Path.Combine(root,@"local-artifacts\installer-v32\HP\AutoCAD2015-2024\AcadBatchPlot.Runtime.dll")));var flags=BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;var scope=asm.GetType("ZwcadBatchPlot.TitleBlockScanScope");var helper=asm.GetType("ZwcadBatchPlot.OpenDrawingScanSpaces").GetMethod("Keys",flags);int all=((IList)helper.Invoke(null,new object[]{doc,Enum.Parse(scope,"AllSpaces")})).Count;int paper=((IList)helper.Invoke(null,new object[]{doc,Enum.Parse(scope,"PaperLayouts")})).Count;int model=((IList)helper.Invoke(null,new object[]{doc,Enum.Parse(scope,"ModelSpace")})).Count;int current=((IList)helper.Invoke(null,new object[]{doc,Enum.Parse(scope,"CurrentSpace")})).Count;if(model!=1||current!=1||all!=paper+model)throw new System.Exception("scope keys mismatch");
using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var p=new Polyline();p.AddVertexAt(0,new Point2d(0,0),0,0,0);p.AddVertexAt(1,new Point2d(420,0),0,0,0);p.AddVertexAt(2,new Point2d(420,297),0,0,0);p.AddVertexAt(3,new Point2d(0,297),0,0,0);p.Closed=true;ms.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);tr.Commit();}
var scanner=asm.GetType("ZwcadBatchPlot.RectangleFrameScanner");var method=scanner.GetMethod("ScanScope",flags);var scan=(IList)method.Invoke(null,new object[]{doc,Enum.Parse(scope,"ModelSpace"),null,false,null,default(System.Threading.CancellationToken),null,false});if(scan.Count<1)throw new System.Exception("unsaved rectangle missing");result="PASS live document scope keys: model/paper/current/all; unsaved in-memory rectangle detected without disk read or document switching";
}catch(System.Exception ex){result="FAIL "+ex;}File.WriteAllText(Path.Combine(root,@"local-artifacts\open-drawings\result.txt"),result);}}
